#!/usr/bin/env python3
"""
Full dev pipeline: run a short simulation (parents + all recursions up to --max-age),
save the persona, then start the conversation server. This is how you test the whole
thing: generation → all layers → chat.

  cd /path/to/Rawlsing
  python3 v2/run_dev_pipeline.py

  Then open http://127.0.0.1:5001 and chat. The persona you're chatting with was
  just generated by the full sim (parents + year-by-year recursion with template
  LLMs). Change sim/recursion/conversation code, re-run this script, refresh the
  page to chat with the newly generated persona.

Options:
  --max-age N     Simulate only ages 1..N (default 7). Higher = more recursions, slower.
  --no-serve      Only run sim and save dev_persona.json; don't start the server.
  --name NAME     Given name for the persona (default Maya).
"""

import json
import os
import sys

_ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
if _ROOT not in sys.path:
    sys.path.insert(0, _ROOT)


def _simulate_parent(role: str, prompt: str) -> str:
    import re
    age = 30
    m = re.search(r"age (\d+) at child's birth", prompt, re.I)
    if m:
        age = int(m.group(1))
    loc = "the region"
    m = re.search(r"Location: ([^\.\n]+)", prompt)
    if m:
        loc = m.group(1).strip()
    warmth = 50
    m = re.search(r"warmth=(\d+)", prompt)
    if m:
        warmth = int(m.group(1))
    authority = 50
    m = re.search(r"authority=(\d+)", prompt)
    if m:
        authority = int(m.group(1))
    t = "?"
    m = re.search(r"Enneagram: Type (\d+)", prompt)
    if m:
        t = m.group(1)
    high_warmth = warmth > 55
    high_auth = authority > 55
    return (
        f"{role.capitalize()}, {age} at the child's birth, grew up in {loc}. "
        f"{'Warm and responsive,' if high_warmth else 'Reserved, emotionally careful,'} "
        f"{'with a strong sense of how things should be done' if high_auth else 'and reluctant to lay down hard rules'}. "
        f"Type {t} shading: carries the weight of unspoken expectations. "
        f"Approaching parenthood with a mix of hope and the fear of repeating what was never named. "
        f"The household holds its breath—the baby will be born into this."
    )


def _simulate_year_delta_json(age: int) -> str:
    """Minimal valid RecursionDelta JSON for a given age (template, no API). Varies by age band so backstory isn't 30 identical lines."""
    if age <= 3:
        stage = "0-3"
        base = "The world pressed in. Small rituals took hold; relationships formed in the cracks. Something in the atmosphere lodged; it would surface later, uninvited."
        extra = {1: "First year: learning who could be trusted.", 2: "Age two: words and boundaries.", 3: "Age three: others outside the house."}.get(age, "")
    elif age <= 7:
        stage = "3-7"
        base = "Safety and warmth were what mattered most. Rituals at the doorframe, a phrase before sleep. Who could be trusted, who could not—the map was forming."
        extra = {4: "Preschool began.", 5: "Kindergarten: the world got bigger.", 6: "First grade.", 7: "Second grade; alliances and exclusions."}.get(age, "")
    elif age <= 11:
        stage = "7-11"
        base = "Belonging and recognition pressed in. Friends, teams, being chosen or left out. Rules at home and school; fairness and who got away with what."
        extra = {8: "Third grade.", 9: "Fourth grade.", 10: "Fifth grade.", 11: "Middle school looming."}.get(age, "")
    elif age <= 16:
        stage = "11-14" if age <= 14 else "17+"
        base = "Identity and peers. Who am I, who are we. Authority—parents, teachers, God—landed in different ways; some absorbed, some resisted."
        extra = {12: "Sixth grade.", 13: "Seventh.", 14: "Eighth.", 15: "High school.", 16: "Driver's permit, first job."}.get(age, "")
    else:
        stage = "17+"
        base = "Coherence and autonomy. Work, relationships, systems. What to cling to, what to reject; the old atmosphere still surfaced sometimes, uninvited."
        extra = {17: "Senior year.", 18: "Graduation; what next.", 21: "Early twenties.", 25: "Mid twenties.", 30: "Thirty."}.get(age, "")
    narrative = f"Age {age}: {base}"
    if extra:
        narrative += " " + extra
    narrative += "."
    return json.dumps({
        "context": {"location": "home", "stage": stage},
        "needs_delta": {},
        "strategy_spikes": {},
        "indices_delta": {},
        "identity_scripts": [],
        "moral_loops": [],
        "narrative": narrative,
    })


def main():
    import argparse
    from v2.spec import (
        IdentitySkeleton,
        simulate_life_course,
        CohortAdjusters,
        build_persona_sheet,
        LLMRecursionResult,
    )
    from v2.data_access import get_world_slice, get_driver_vec, get_local_modifiers

    parser = argparse.ArgumentParser(description="Run full dev pipeline: short sim + chat server")
    parser.add_argument("--max-age", type=int, default=7, help="Simulate ages 1..N (default 7)")
    parser.add_argument("--no-serve", action="store_true", help="Only run sim and save persona; do not start server")
    parser.add_argument("--name", default="Maya", help="Given name for the persona")
    args = parser.parse_args()

    max_age = max(1, min(args.max_age, 35))
    birth_year = 2025 - max_age
    identity = IdentitySkeleton(
        internal_id=f"dev_{args.name.lower()}_001",
        given_name=args.name,
        family_name="Chen",
        gender="female",
        birth_year=birth_year,
        anchor_year=2025,
        age_at_anchor=max_age,
        country_code="US",
        region="California",
        locality="Oakland",
        urbanicity="city",
        class_origin="middle",
        current_class="middle",
        ethnicity_label="Asian",
        minority_status="minoritized",
        childhood_religion="None",
        current_religion="None",
        religiosity_level=20.0,
        primary_language="English",
        secondary_languages=[],
    )

    parent_prompts, parent_responses = [], []
    year_responses = []

    def parent_llm(role: str, prompt: str) -> str:
        parent_prompts.append((role, prompt))
        resp = _simulate_parent(role, prompt)
        parent_responses.append((role, resp))
        return resp

    def llm_cb(state, prompt: str):
        age = getattr(state, "age", 1)
        resp = _simulate_year_delta_json(age)
        year_responses.append((age, resp))
        return LLMRecursionResult(narrative=resp, idea_delta=None)

    print("Running simulation: parents + ages 1..{} (template LLMs, no API)...".format(max_age))
    try:
        history = simulate_life_course(
            identity=identity,
            adjusters=CohortAdjusters(),
            constraints=None,
            get_world_slice=get_world_slice,
            get_driver_vec=get_driver_vec,
            get_local_modifiers=get_local_modifiers,
            parent_llm_callback=parent_llm,
            llm_callback=llm_cb,
            use_delta_schema=True,
        )
    except Exception as e:
        print("Simulation failed:", e)
        import traceback
        traceback.print_exc()
        return 1

    sheet = build_persona_sheet(history)
    out_path = os.path.join(_ROOT, "dev_persona.json")
    with open(out_path, "w") as f:
        json.dump(sheet, f, indent=2, default=str)
    print("Saved persona to", out_path)

    if args.no_serve:
        print("Skipping server (--no-serve). Start it with:")
        print("  DEV_PERSONA_JSON=dev_persona.json python3 v2/conversation_test_server.py")
        return 0

    # Start conversation server using the persona we just wrote
    os.environ["DEV_PERSONA_JSON"] = out_path
    print("Starting conversation server at http://127.0.0.1:5001 ...")
    print("Open that URL and chat. This persona was just generated by the full sim.")
    # Import and run the server's app
    from v2.conversation_test_server import main as server_main
    server_main()
    return 0


if __name__ == "__main__":
    sys.exit(main())
